/*
 * Regression: interoperability with files produced by MuPDF's mutool.
 *
 * encrypted-mutool-aes256.pdf uses /V 5 /R 6 /CFM /AESV3 (AES-256-CBC with
 * SHA-2 based Algorithm 2.B password hashing); the aes128 fixture uses
 * /V 4 /R 4 /CFM /AESV2. Both were generated by `mutool clean -E` with an
 * empty user password, so they pin the reader against a real producer rather
 * than the package's own generator.
 *
 * Fixtures come from tests/data/make_mutool_encrypted.py.
 */

#include "document_backend.h"

#include <quirewise/document.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int read_file(const char *path, uint8_t **out_data, size_t *out_size)
{
    FILE *file = fopen(path, "rb");
    long length;
    uint8_t *buffer;
    if (!file) return 0;
    if (fseek(file, 0, SEEK_END) != 0 || (length = ftell(file)) < 0 ||
        fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        return 0;
    }
    buffer = (uint8_t *)malloc((size_t)length);
    if (!buffer) {
        fclose(file);
        return 0;
    }
    if (fread(buffer, 1u, (size_t)length, file) != (size_t)length) {
        free(buffer);
        fclose(file);
        return 0;
    }
    fclose(file);
    *out_data = buffer;
    *out_size = (size_t)length;
    return 1;
}

static int contains(const char *data, size_t size, const char *text)
{
    size_t length = strlen(text);
    size_t index;
    if (!length || size < length) return 0;
    for (index = 0u; index + length <= size; ++index) {
        if (memcmp(data + index, text, length) == 0) return 1;
    }
    return 0;
}

static int check_document(const char *label, const char *path)
{
    uint8_t *data = NULL;
    size_t size = 0u;
    QwPdfReader *reader = NULL;
    size_t pages = 0u;
    QwConvertReport report;
    uint8_t *text = NULL;
    size_t text_size = 0u;
    int rc;

    if (!read_file(path, &data, &size)) {
        fprintf(stderr, "%s: could not read %s\n", label, path);
        return 1;
    }
    memset(&report, 0, sizeof(report));
    rc = qw_pdf_reader_open(data, size, &reader, &pages, &report);
    if (rc != 0 || !reader || pages != 1u) {
        fprintf(stderr, "%s: open rc=%d pages=%zu note=%s\n", label, rc, pages,
                report.note);
        free(data);
        if (reader) qw_pdf_reader_close(reader);
        return 2;
    }
    rc = qw_pdf_reader_extract_text(reader, &text, &text_size, &report);
    qw_pdf_reader_close(reader);
    free(data);
    if (rc != 0 || !text) {
        fprintf(stderr, "%s: extract rc=%d note=%s\n", label, rc, report.note);
        free(text);
        return 3;
    }
    if (!contains((const char *)text, text_size, "AES256 mutool hello")) {
        fprintf(stderr, "%s: decrypted text missing (%.*s)\n", label,
                (int)(text_size > 120u ? 120u : text_size), text);
        free(text);
        return 4;
    }
    free(text);
    return 0;
}

/* Flip one nibble of /U so the password check fails. */
static int tamper_user_key(const char *path)
{
    uint8_t *data = NULL;
    size_t size = 0u;
    QwPdfReader *reader = NULL;
    size_t pages = 0u;
    size_t position = 0u;
    int tampered = 0;
    int rc;
    if (!read_file(path, &data, &size)) return 10;
    while (position + 3u < size) {
        if (data[position] == '/' && data[position + 1u] == 'U' &&
            data[position + 2u] == '<') {
            size_t cursor = position + 3u;
            while (cursor < size && data[cursor] != '>') {
                if (data[cursor] >= '0' && data[cursor] <= '9') {
                    data[cursor] = (uint8_t)(data[cursor] == '0' ? '1' : '0');
                    tampered = 1;
                    break;
                }
                ++cursor;
            }
            break;
        }
        ++position;
    }
    if (!tampered) {
        free(data);
        return 11;
    }
    rc = qw_pdf_reader_open(data, size, &reader, &pages, NULL);
    free(data);
    if (reader) qw_pdf_reader_close(reader);
    return rc == 0 ? 12 : 0;
}

/* A document with a non-empty user password must fail the full open but still
 * expose page count and geometry through the structure-only path. */
static int check_structure_only(const char *path)
{
    uint8_t *data = NULL;
    size_t size = 0u;
    QwPdfReader *reader = NULL;
    size_t pages = 0u;
    QwConvertReport report;
    double media[4];
    double crop[4];
    int rotation = -1;
    int rc;

    if (!read_file(path, &data, &size)) {
        fprintf(stderr, "structure: could not read %s\n", path);
        return 1;
    }
    memset(&report, 0, sizeof(report));
    rc = qw_pdf_reader_open(data, size, &reader, &pages, &report);
    if (rc == QW_STATUS_OK) {
        fprintf(stderr, "structure: full open accepted a user-password PDF\n");
        if (reader) qw_pdf_reader_close(reader);
        free(data);
        return 2;
    }
    reader = NULL;
    memset(&report, 0, sizeof(report));
    rc = qw_pdf_reader_open_structure(data, size, &reader, &pages, &report);
    if (rc != QW_STATUS_OK || !reader || pages != 1u) {
        fprintf(stderr, "structure: open rc=%d pages=%zu note=%s\n", rc, pages,
                report.note);
        if (reader) qw_pdf_reader_close(reader);
        free(data);
        return 3;
    }
    rc = qw_pdf_reader_page_geometry(reader, 0u, media, crop, &rotation);
    if (rc != QW_STATUS_OK || media[2] <= media[0] || media[3] <= media[1]) {
        fprintf(stderr, "structure: geometry rc=%d\n", rc);
        qw_pdf_reader_close(reader);
        free(data);
        return 4;
    }
    {
        uint8_t *text = NULL;
        size_t text_size = 0u;
        rc = qw_pdf_reader_extract_text(reader, &text, &text_size, &report);
        free(text);
        if (rc == QW_STATUS_OK) {
            fprintf(stderr, "structure: content decrypted without password\n");
            qw_pdf_reader_close(reader);
            free(data);
            return 5;
        }
    }
    qw_pdf_reader_close(reader);
    free(data);
    return 0;
}

int main(void)
{
    int rc = check_document("mutool aes256",
                            QUIREWISE_MUTOOL_AES256_PDF);
    if (rc != 0) return rc;
    rc = check_document("mutool aes128", QUIREWISE_MUTOOL_AES128_PDF);
    if (rc != 0) return rc;
    rc = tamper_user_key(QUIREWISE_MUTOOL_AES256_PDF);
    if (rc != 0) {
        fprintf(stderr, "tampered /U was not rejected (rc=%d)\n", rc);
        return 5;
    }
    rc = check_structure_only(QUIREWISE_MUTOOL_AES256_USERPW_PDF);
    if (rc != 0) return 6 + rc;
    return 0;
}
